INSERT INTO research_paper (paper_id, title, abstract, authors, category, publication_date, user_id)
VALUES (1, 'Attention Is All You Need', 'The dominant sequence transduction models are based on complex recurrent or convolutional neural networks that include an encoder and a decoder. We propose a new simple network architecture, the Transformer, based solely on attention mechanisms, dispensing with recurrence and convolutions entirely.', 'Vaswani et al.', 'Natural Language Processing', '2017-06-12', 1)
ON CONFLICT (paper_id) DO NOTHING;

