INSERT INTO research_paper (paper_id, title, abstract, authors, category, publication_date, user_id)
VALUES (2, 'Deep Residual Learning for Image Recognition', 'Deeper neural networks are more difficult to train. We present a residual learning framework to ease the training of networks that are substantially deeper than those used previously. We explicitly reformulate the layers as learning residual functions with reference to the layer inputs, instead of learning unreferenced functions.', 'He et al.', 'Computer Vision', '2015-12-10', 1)
ON CONFLICT (paper_id) DO NOTHING;

