INSERT INTO research_paper (paper_id, title, abstract, authors, category, publication_date, user_id)
VALUES (3, 'BERT: Pre-training of Deep Bidirectional Transformers for Language Understanding', 'We introduce a new language representation model called BERT, which stands for Bidirectional Encoder Representations from Transformers. Unlike recent language representation models, BERT is designed to pre-train deep bidirectional representations from unlabeled text by jointly conditioning on both left and right context in all layers.', 'Devlin et al.', 'Natural Language Processing', '2018-10-11', 1)
ON CONFLICT (paper_id) DO NOTHING;

