INSERT INTO research_paper (paper_id, title, abstract, authors, category, publication_date, user_id)
VALUES (4, 'AlphaFold: Highly accurate protein structure prediction', 'Proteins are essential to life, and understanding their structure can facilitate a mechanistic understanding of their function. Here we develop a deep learning model, AlphaFold, which demonstrates unprecedented atomic-level accuracy in predicting 3D structures of proteins directly from primary amino acid sequences.', 'Jumper et al.', 'Computational Biology', '2021-07-15', 1)
