INSERT INTO research_paper (paper_id, title, abstract, authors, category, publication_date, user_id)
VALUES (5, 'Architecture of a Database System', 'Database management systems (DBMSs) were among the earliest multi-user software systems. This paper presents an architectural overview of modern relational database management systems, covering storage engines, query compilation, cost-based query optimization, concurrency control, and ACID transaction recovery.', 'Hellerstein, Stonebraker, Hamilton', 'Database Systems', '2007-08-01', 1)
ON CONFLICT (paper_id) DO NOTHING;

