INSERT INTO research_paper (paper_id, title, abstract, authors, category, publication_date, user_id)
VALUES (6, 'Efficient and Robust Approximate Nearest Neighbor Search Using Hierarchical Navigable Small World (HNSW) Graphs', 'We present the Hierarchical Navigable Small World (HNSW) graph technique for approximate nearest neighbor search in high-dimensional vector spaces. HNSW provides logarithmic search scaling, high recall, and robust performance across Euclidean and Cosine vector distance metrics, outperforming traditional tree-based partitioning.', 'Malkov and Yashunin', 'Vector Databases', '2018-03-20', 1)
ON CONFLICT (paper_id) DO NOTHING;

