INSERT INTO research_paper (paper_id, title, abstract, authors, category, publication_date, user_id)
VALUES (7, 'Retrieval-Augmented Generation for Knowledge-Intensive NLP Tasks', 'Large pre-trained language models have been shown to store factual knowledge in their parameters. We propose Retrieval-Augmented Generation (RAG) models which combine pre-trained parametric and non-parametric memory through dense vector retrieval over document indexes, achieving state-of-the-art results on open-domain question answering.', 'Lewis et al.', 'Information Retrieval', '2020-05-22', 1)
ON CONFLICT (paper_id) DO NOTHING;

