INSERT INTO research_paper (paper_id, title, abstract, authors, category, publication_date, user_id)
VALUES (8, 'The Anatomy of a Large-Scale Hypertextual Web Search Engine', 'In this paper, we present Google, a prototype of a large-scale search engine which makes heavy use of the structure present in hypertext. Google is designed to crawl and index the Web efficiently and produce much more satisfying search results than existing systems using PageRank citation graph analysis.', 'Brin and Page', 'Information Retrieval', '1998-04-14', 1)
ON CONFLICT (paper_id) DO NOTHING;

